  function appState(){try{return typeof state!=="undefined"&&state?state:null}catch(e){return null}}
  async function resolveUser(){
    const client=appClient();
    try{if(client?.auth){const r=await client.auth.getUser();if(r?.data?.user?.id)return r.data.user.id}}catch(e){}
    try{if(typeof authUser!=="undefined"&&authUser?.id)return authUser.id}catch(e){}
    const m=appMember(),s=appState();
    return m?.auth_user_id||m?.user_id||s?.member?.auth_user_id||s?.member?.user_id||"guest";
  }
  function boardLocalKey(){return`inbestiga_ca_board:${userId}:${BOARD_KEY}`}
