  function table(name){try{const client=appClient();return client?.schema?client.schema("marketing_app").from(name):null}catch(e){return null}}

  function normalizeBoard(){
    board.elements=Array.isArray(board.elements)?board.elements:[];
    board.connections=Array.isArray(board.connections)?board.connections:[];
    board.drawings=Array.isArray(board.drawings)?board.drawings:[];
    board.comments=Array.isArray(board.comments)?board.comments:[];
    board.revision=Number(board.revision)||Date.now();
    prefs.loadout=Array.isArray(prefs.loadout)&&prefs.loadout.length?[...new Set(prefs.loadout.filter(t=>toolRunes[t]))].slice(0,6):defaultPrefs().loadout.slice();
    while(prefs.loadout.length<6)prefs.loadout.push(defaultPrefs().loadout.find(t=>!prefs.loadout.includes(t))||"select");
    board.elements.forEach(o=>{if(o.locked==null)o.locked=false;if(o.opacity==null)o.opacity=1;if(o.type==="story"){o.status=o.status||"idea";o.owner=o.owner||"";o.duration=o.duration||"00:15";o.priority=o.priority||"media";o.dialog=o.dialog||"";o.audio=o.audio||""}});
    shopCategory=prefs.shopCategory||"all";currentFontSize=Math.max(10,Math.min(96,Number(prefs.fontSize)||26));currentColor=prefs.currentColor||prefs.accent||"#ef9c41";currentSize=Math.max(1,Math.min(28,Number(prefs.brushSize)||4));currentShape=prefs.shape&&["round","circle","diamond","triangle","star","arrow","line","rect"].includes(prefs.shape)?prefs.shape:"round";prefs.surface=["glass","solid","minimal"].includes(prefs.surface)?prefs.surface:"glass";prefs.density=["compact","comfortable","spacious"].includes(prefs.density)?prefs.density:"comfortable";prefs.cornerRadius=Math.max(10,Math.min(28,Number(prefs.cornerRadius)||18));prefs.glow=Math.max(0,Math.min(100,Number(prefs.glow)||55));prefs.customThemes=Array.isArray(prefs.customThemes)?prefs.customThemes.slice(0,8):[];
  }
  async function loadData(){
    prefs=defaultPrefs();board=defaultBoard();
    try{const raw=localStorage.getItem(prefsLocalKey());if(raw)prefs={...prefs,...JSON.parse(raw)}}catch(e){}
    try{const raw=localStorage.getItem(boardLocalKey());if(raw)board={...board,...JSON.parse(raw)}}catch(e){}
    const pt=table("creative_arena_preferences");
    if(pt&&userId!=="guest")try{const r=await pt.select("preferences").eq("user_id",userId).maybeSingle();if(r.data?.preferences)prefs={...prefs,...r.data.preferences}}catch(e){}
    let sharedLoaded=false;
    const st=table("creative_arena_shared_boards");
    if(st&&userId!=="guest")try{const r=await st.select("title,board_state,revision").eq("board_key",BOARD_KEY).maybeSingle();if(r.data?.board_state){board={...board,...r.data.board_state,title:r.data.title||board.title,revision:Number(r.data.revision)||Date.now()};sharedLoaded=true}}catch(e){}
    if(!sharedLoaded){const bt=table("creative_arena_boards");if(bt&&userId!=="guest")try{const r=await bt.select("title,board_state").eq("user_id",userId).eq("board_key",BOARD_KEY).maybeSingle();if(r.data?.board_state)board={...board,...r.data.board_state};if(r.data?.title)board.title=r.data.title}catch(e){}}
    normalizeBoard();
  }
