  function renderRemoteCursors(){const host=$("caRemoteCursors");if(!host||!stage)return;const mine=String(userId);const people=presenceMembers.filter(p=>String(p.user_id||"")!==mine&&p.cursor&&Number.isFinite(Number(p.cursor.x))&&Number.isFinite(Number(p.cursor.y)));host.innerHTML=people.map(p=>{const sx=Number(p.cursor.x)*stage.scaleX()+stage.x(),sy=Number(p.cursor.y)*stage.scaleY()+stage.y(),name=p.name||"Miembro",avatar=p.avatar||"",color=p.color||"#8f6bff";return`<div class="ca-remote-cursor" style="transform:translate(${sx}px,${sy}px);--cursor-color:${esc(color)}"><i></i><span>${avatar?`<img src="${esc(avatar)}" alt="">`:esc(initials(name))}</span><b>${esc(name)}</b></div>`}).join("")}
