    stage.on("mousemove touchmove",e=>{const p=pointer();lastCursor={x:p.x,y:p.y};schedulePresence();renderRemoteCursors();if(tool==="eraser"&&e.evt){const r=$("caBoardWrap").getBoundingClientRect(),c=$("caEraserCursor");c.style.display="block";c.style.width=`${currentSize*3+12}px`;c.style.height=`${currentSize*3+12}px`;c.style.left=`${e.evt.clientX-r.left}px`;c.style.top=`${e.evt.clientY-r.top}px`}if(marqueeStart&&tool==="select"){selectionRect.size({width:p.x-marqueeStart.x,height:p.y-marqueeStart.y});uiLayer.batchDraw()}if(drawing){drawing.points.push(p.x,p.y);inkRender()}});
    stage.on("mouseup touchend",()=>{stage.draggable(false);if(marqueeStart){const box=selectionRect.getClientRect();selected=[...nodes.entries()].filter(([,n])=>Konva.Util.haveIntersection(box,n.getClientRect())).map(([id])=>id);selectionRect.visible(false);marqueeStart=null;selectRender();schedulePresence()}if(drawing){drawing=null;broadcastOperation("drawing-sync",{drawings:board.drawings});save("Trazo guardado")}saveCamera();renderRemoteCursors()});
