  function applyRemoteBoard(remote){if(!remote||remote.sender===userId||!remote.board)return;const incoming=Number(remote.board.revision)||0;if(incoming<=(Number(board.revision)||0))return;applyingRemote=true;const cameraNow=board.camera;board={...board,...remote.board,camera:cameraNow||remote.board.camera};normalizeBoard();writeLocal();render();applyingRemote=false;toast("Cambio del equipo recibido")}
