  function hotkeys(e){if(!root||!root.isConnected||!q("#creativeRoomsClean.active")&&!q("#creativeRoomsClean.section.active"))return;if(e.key==="Escape"&&$("caShop")?.classList.contains("open")){e.preventDefault();$("caShop").classList.remove("open");$("caShop").setAttribute("aria-hidden","true");$("caShopToggle")?.setAttribute("aria-expanded","false");root.classList.remove("ca-shop-open");return}const tag=e.target?.tagName?.toLowerCase();if(["input","textarea","select"].includes(tag))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="z"){e.preventDefault();return undo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="y"){e.preventDefault();return redo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="c"){e.preventDefault();return copy()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="v"){e.preventDefault();return paste()}if(e.key==="Delete"||e.key==="Backspace"){e.preventDefault();return remove()}if(/^[1-6]$/.test(e.key)){const t=prefs.loadout[Number(e.key)-1];if(t){e.preventDefault();setTool(t)}return}const map={v:"select",m:"pan",n:"note",t:"text",s:"story",p:"draw",e:"eraser",f:"shape",c:"connector"};if(map[e.key.toLowerCase()])setTool(map[e.key.toLowerCase()])}
  function templateAdd(type){const p=pointer();if(type==="idea")add("note",p,{text:"BIG IDEA\n\nHook:\nInsight:\nCTA:",fill:"#efca70",w:230,h:190});else if(type==="scene")add("story",p);else if(type==="plan")add("story",p,{title:"Plan de grabacion",tasks:"Locacion\nUtileria\nVestuario\nEquipo\nPermisos"});else if(type==="six"){snapshot();for(let i=0;i<6;i++)add("story",{x:120+(i%2)*390,y:130+Math.floor(i/2)*310},{title:`Escena ${i+1}`,scene:String(i+1).padStart(2,"0")});fit()}else if(type==="mood"){add("frame",p,{title:"MOODBOARD",w:540,h:350,stroke:"#83b5ff"});add("note",{x:p.x+35,y:p.y+60},{text:"Referencias visuales\nPaleta\nFotografia\nTexturas",fill:"#d9dce5",w:210,h:180})}else if(type==="calendar"){add("frame",p,{title:"CONTENT CALENDAR",w:520,h:320,stroke:prefs.accent});add("text",{x:p.x+30,y:p.y+65},{text:"MON  TUE  WED  THU  FRI\n\nIdea   Script   Shoot   Edit   Publish",fontSize:20,w:440,h:160})}}

